package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// The shape of StackLab's gorun: shared code plus one file per OS family.
var files = map[string]string{
	"go.mod": "module example.com/runner\n\ngo 1.27\n",
	"main.go": `package main

import "fmt"

func main() { fmt.Println(killTree(42)) }
`,
	// The _windows suffix is a build constraint by itself.
	"proc_windows.go": `package main

import "fmt"

func killTree(pid int) string { return fmt.Sprintf("TerminateJobObject (job of %d)", pid) }
`,
	// No suffix for "unix", so the constraint is spelled out.
	"proc_unix.go": `//go:build unix

package main

import "fmt"

func killTree(pid int) string { return fmt.Sprintf("kill -KILL -%d (process group)", pid) }
`,
}

func main() {
	dir, err := os.MkdirTemp("", "runner-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(dir)
	for name, body := range files {
		if err := os.WriteFile(filepath.Join(dir, name), []byte(body), 0o644); err != nil {
			panic(err)
		}
	}

	for _, target := range []string{"linux/amd64", "darwin/arm64", "windows/amd64", "plan9/amd64"} {
		goos, goarch, _ := strings.Cut(target, "/")
		cmd := exec.Command("go", "list", "-f", "{{.GoFiles}} ignored: {{.IgnoredGoFiles}}", ".")
		cmd.Dir = dir
		cmd.Env = append(os.Environ(), "GOTOOLCHAIN=local", "GOPROXY=off",
			"GOOS="+goos, "GOARCH="+goarch, "CGO_ENABLED=0")
		out, err := cmd.CombinedOutput()
		if err != nil {
			panic(fmt.Sprint(err, string(out)))
		}
		fmt.Printf("%-14s %s", target, out)
	}
}

files.examples/02_ship_binaries.go:
package main

import (
	"bytes"
	"debug/buildinfo"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

const app = `package main

import "fmt"

var version = "dev" // overwritten at link time by -X main.version=...

func main() { fmt.Println("stacklab", version) }
`

func main() {
	os.MkdirAll("ship", 0o755) // the runner starts in a fresh directory
	write("ship/go.mod", "module example.com/stacklab\n\ngo 1.27\n")
	write("ship/main.go", app)

	ldflags := "-s -X main.version=v1.4.2"
	for _, target := range []string{"linux/amd64", "linux/arm64", "darwin/arm64", "windows/amd64"} {
		goos, goarch, _ := strings.Cut(target, "/")
		out := "dist/stacklab-" + goos + "-" + goarch
		gocmd([]string{"GOOS=" + goos, "GOARCH=" + goarch, "CGO_ENABLED=0"},
			"build", "-trimpath", "-ldflags="+ldflags, "-o", out, ".")

		bin, err := os.ReadFile("ship/" + out)
		if err != nil {
			panic(err)
		}
		info, err := buildinfo.Read(bytes.NewReader(bin)) // any target's format
		if err != nil {
			panic(err)
		}
		set := map[string]string{}
		for _, s := range info.Settings {
			set[s.Key] = s.Value
		}
		fmt.Printf("%-14s %-6s CGO_ENABLED=%s -trimpath=%s -ldflags recorded: %v\n", target,
			format(bin), set["CGO_ENABLED"], set["-trimpath"], set["-ldflags"] != "")
	}

	// Only a build for this machine can run here; -X works the same for go run.
	fmt.Print("go run here: ", gocmd(nil, "run", "-ldflags="+ldflags, "."))
}

// format names the executable format by the file's first bytes.
func format(bin []byte) string {
	for magic, name := range map[string]string{"\x7fELF": "ELF", "MZ": "PE", "\xcf\xfa\xed\xfe": "Mach-O"} {
		if bytes.HasPrefix(bin, []byte(magic)) {
			return name
		}
	}
	return "?"
}

func gocmd(env []string, args ...string) string {
	cmd := exec.Command("go", args...)
	cmd.Dir = "ship"
	cmd.Env = append(os.Environ(), env...)
	out, err := cmd.CombinedOutput()
	if err != nil {
		panic(fmt.Sprint(err, string(out)))
	}
	return string(out)
}

func write(path, body string) {
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		panic(err)
	}
}

files.examples/03_vcs_version.go:
package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strings"
)

// The app prints its own version: go build stamps it, no -ldflags needed.
const app = `package main

import (
	"fmt"
	"runtime/debug"
)

func main() {
	info, _ := debug.ReadBuildInfo()
	fmt.Println(info.Main.Version)
}
`

func main() {
	os.MkdirAll("repo", 0o755) // the runner starts in a fresh directory
	write("repo/go.mod", "module example.com/stacklab\n\ngo 1.27\n")
	write("repo/main.go", app)

	run("git", "init", "-q")
	run("git", "add", ".")
	run("git", "commit", "-q", "-m", "first release")
	run("git", "tag", "v1.4.2")
	fmt.Println("tagged commit:       ", buildAndRun())

	write("repo/main.go", app+"\n// work in progress\n")
	fmt.Println("uncommitted change:  ", buildAndRun())

	run("git", "commit", "-q", "-am", "after the release")
	fmt.Println("commit after the tag:", buildAndRun())
}

var rev = regexp.MustCompile(`-[0-9a-f]{12}$`) // the commit hash part

// buildAndRun writes the binary outside the repository: inside, it would be
// an untracked file, and that counts as a modification.
func buildAndRun() string {
	run("go", "build", "-o", "../bin/app.exe", ".")
	out, err := exec.Command("bin/app.exe").Output()
	if err != nil {
		panic(err)
	}
	return rev.ReplaceAllString(strings.TrimSpace(string(out)), "-<rev12>")
}

// run executes a command in repo with a fixed git identity and clock and
// without the user's git configuration, so every run makes the same history.
func run(name string, args ...string) {
	cmd := exec.Command(name, args...)
	cmd.Dir = "repo"
	cmd.Env = append(os.Environ(), "GIT_CONFIG_GLOBAL=../no-gitconfig", "GIT_CONFIG_NOSYSTEM=1",
		"GIT_AUTHOR_NAME=ayse", "GIT_AUTHOR_EMAIL=ayse@example.com",
		"GIT_COMMITTER_NAME=ayse", "GIT_COMMITTER_EMAIL=ayse@example.com",
		"GIT_AUTHOR_DATE=2026-11-02T09:00:00Z", "GIT_COMMITTER_DATE=2026-11-02T09:00:00Z")
	if out, err := cmd.CombinedOutput(); err != nil {
		panic(fmt.Sprint(name, args, err, string(out)))
	}
}

func write(path, body string) {
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		panic(err)
	}
}
